mapper.select:
select
lawyers.*
from lawyers lawyers

    and lawyers.id = #{id}
    and lawyers.name like concat('%',#{name},'%')
    and lawyers.avatar = #{avatar}
    and lawyers.email = #{email}
    and lawyers.level = #{level}
    and lawyers.info = #{info}
    and lawyers.certificate = #{certificate}
    and lawyers.age = #{age}
    and lawyers.sex = #{sex}
    and lawyers.status = #{status}
    and lawyers.create_time = #{createTime}


    limit #{current},#{pageSize}

select count(*) from lawyers lawyers

    and lawyers.id = #{id}
    and lawyers.name like concat('%',#{name},'%')
    and lawyers.avatar = #{avatar}
    and lawyers.email = #{email}
    and lawyers.level = #{level}
    and lawyers.info = #{info}
    and lawyers.certificate = #{certificate}
    and lawyers.age = #{age}
    and lawyers.sex = #{sex}
    and lawyers.status = #{status}
    and lawyers.create_time = #{createTime}
